create policy ur_checkins_read on public.ur_play_checkins for select to authenticated using(private.operates_ur_play_session(session_id)or athlete_id=private.current_athlete_id());create policy ur_checkins_admin on public.ur_play_checkins for all to authenticated using(private.has_any_role(array['admin']::public.app_role[]))with check(private.has_any_role(array['admin']::public.app_role[]));
create policy ur_staff_read on public.ur_play_session_staff for select to authenticated using(private.has_any_role(array['admin']::public.app_role[])or profile_id=auth.uid());create policy ur_staff_admin on public.ur_play_session_staff for all to authenticated using(private.has_any_role(array['admin']::public.app_role[]))with check(private.has_any_role(array['admin']::public.app_role[]));
